-- Riverside Clinics (Healthcare, fully synthetic)
-- Generated by gen_datasets.py with a fixed seed. Fictional data.

DROP TABLE IF EXISTS prescriptions; DROP TABLE IF EXISTS appointment_diagnoses; DROP TABLE IF EXISTS diagnoses; DROP TABLE IF EXISTS appointments;
DROP TABLE IF EXISTS patients; DROP TABLE IF EXISTS doctors; DROP TABLE IF EXISTS departments;
CREATE TABLE departments (department_id INT PRIMARY KEY, department_name VARCHAR(60) COLLATE NOCASE NOT NULL, floor INT);
CREATE TABLE doctors (doctor_id INT PRIMARY KEY, department_id INT REFERENCES departments(department_id), first_name VARCHAR(60) COLLATE NOCASE, last_name VARCHAR(60) COLLATE NOCASE, specialty VARCHAR(60) COLLATE NOCASE,
  supervisor_id INT REFERENCES doctors(doctor_id), hire_date DATE, consultation_fee DECIMAL(8,2));
CREATE TABLE patients (patient_id INT PRIMARY KEY, first_name VARCHAR(60) COLLATE NOCASE, last_name VARCHAR(60) COLLATE NOCASE, gender VARCHAR(60) COLLATE NOCASE, birth_year INT, city VARCHAR(60) COLLATE NOCASE, registered_date DATE, insurance_provider VARCHAR(60) COLLATE NOCASE);
CREATE TABLE appointments (appointment_id INT PRIMARY KEY, patient_id INT REFERENCES patients(patient_id), doctor_id INT REFERENCES doctors(doctor_id),
  scheduled_at DATETIME, status VARCHAR(60) COLLATE NOCASE, wait_minutes INT);
CREATE TABLE diagnoses (diagnosis_code VARCHAR(5) COLLATE NOCASE PRIMARY KEY, description VARCHAR(60) COLLATE NOCASE, category VARCHAR(60) COLLATE NOCASE);
CREATE TABLE appointment_diagnoses (appointment_id INT REFERENCES appointments(appointment_id), diagnosis_code VARCHAR(5) REFERENCES diagnoses(diagnosis_code),
  PRIMARY KEY (appointment_id, diagnosis_code));
CREATE TABLE prescriptions (prescription_id INT PRIMARY KEY, appointment_id INT REFERENCES appointments(appointment_id), drug_name VARCHAR(60) COLLATE NOCASE, days_supplied INT, cost DECIMAL(8,2));







